def source(t):
    body = '\n'.join('        ' + line for line in t['code'].splitlines())
    decl = '\n'.join('    ' + line for line in t['declarations'].splitlines())
    return imports + '\npublic class Demo {\n' + decl + ('\n\n' if decl else '') + '    public static void main(String[] args) throws Exception {\n' + body + '\n    }\n}\n'

